<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_login();$id=(int)($_GET['id']??0);$q=db()->prepare('SELECT title FROM projects WHERE id=?');$q->execute([$id]);$title=$q->fetchColumn();if(!$title){http_response_code(404);exit('Project not found');}$q=db()->prepare('SELECT r.*,u.name user_name FROM project_revisions r LEFT JOIN users u ON u.id=r.user_id WHERE r.project_id=? ORDER BY r.created_at DESC');$q->execute([$id]);$rows=$q->fetchAll();$pageTitle='Project Revision History';require __DIR__.'/../../includes/admin_header.php';?><p>Project: <?=e($title)?></p><table border="1" cellpadding="6"><tr><th>Revision</th><th>Saved by</th><th>Date</th><th>Snapshot</th></tr><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=e($r['user_name']??'System')?></td><td><?=e($r['created_at'])?></td><td><details><summary>View saved data</summary><pre><?=e(json_encode(json_decode($r['revision_data'],true),JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE))?></pre></details></td></tr><?php endforeach;?></table><?php require __DIR__.'/../../includes/admin_footer.php';
